import click

@click.command()
@click.option('--size', type=click.BYTE_SIZE, help='A byte size value')
def test_cmd(size):
    if size:
        click.echo(f'Size: {size} bytes')

# Test valid inputs
from click.testing import CliRunner
runner = CliRunner()

test_cases = [
    (['--size', '512'], 'Size: 512 bytes'),
    (['--size', '1KB'], 'Size: 1000 bytes'),
    (['--size', '1.5MB'], 'Size: 1500000 bytes'),
    (['--size', '1GiB'], 'Size: 1073741824 bytes'),
]

for args, expected in test_cases:
    result = runner.invoke(test_cmd, args)
    if result.exit_code == 0 and expected in result.output:
        print(f'✓ {args} -> {expected}')
    else:
        print(f'✗ {args} failed: {result.output}')

# Test invalid input
result = runner.invoke(test_cmd, ['--size', 'invalid'])
if result.exit_code != 0:
    print('✓ Invalid input rejected')
else:
    print('✗ Invalid input not rejected')
